CREATE TABLE legal_review_cases (case_id TEXT PRIMARY KEY, contract_id TEXT NOT NULL, governing_office_id TEXT NOT NULL, governing_office_name TEXT NOT NULL, requester_person_id TEXT NOT NULL, requester_name TEXT NOT NULL, case_owner_person_id TEXT NOT NULL, case_owner_name TEXT NOT NULL, priority TEXT NOT NULL CHECK (priority IN ('CRITICAL','HIGH','MEDIUM','LOW')), case_state TEXT NOT NULL CHECK (case_state IN ('INTAKE','IN_REVIEW','PENDING_REQUESTER','CLOSED')), intake_timestamp_et TEXT NOT NULL, contract_receipt_timestamp_et TEXT NOT NULL, requested_return_deadline_et TEXT NOT NULL, planning_benchmark_deadline_et TEXT NOT NULL, sla_policy_id TEXT NOT NULL, checklist_status TEXT NOT NULL, short_description TEXT NOT NULL, FOREIGN KEY (case_owner_person_id) REFERENCES legal_review_cases(case_owner_person_id));

CREATE TABLE deficiency_items (deficiency_item_id TEXT PRIMARY KEY, case_id TEXT NOT NULL, source_evaluation_id TEXT NOT NULL, source_evaluation_status_snapshot TEXT NOT NULL CHECK (source_evaluation_status_snapshot IN ('ACTIVE','SUPERSEDED','WITHDRAWN')), checklist_code TEXT NOT NULL, deficiency_title TEXT NOT NULL, deficiency_detail TEXT NOT NULL, assigned_person_id TEXT NOT NULL, assigned_person_name TEXT NOT NULL, due_timestamp_et TEXT NOT NULL, item_state TEXT NOT NULL CHECK (item_state IN ('OPEN','AWAITING_REQUESTER','IN_PROGRESS','RESOLVED','CLOSED')), duplicate_of_item_id TEXT, created_timestamp_et TEXT NOT NULL, resolved_timestamp_et TEXT, FOREIGN KEY (case_id) REFERENCES legal_review_cases(case_id), FOREIGN KEY (duplicate_of_item_id) REFERENCES deficiency_items(deficiency_item_id));

CREATE TABLE sla_events (sla_event_id TEXT PRIMARY KEY, case_id TEXT NOT NULL, event_type TEXT NOT NULL CHECK (event_type IN ('CLOCK_STARTED','PAUSED','RESUMED','BREACH_FORECAST','EXCEPTION_REQUESTED','EXCEPTION_APPROVED','NOTICE_ISSUED')), event_timestamp_et TEXT NOT NULL, effective_deadline_et TEXT NOT NULL, approval_route_id TEXT, approval_decision TEXT CHECK (approval_decision IN ('PENDING','APPROVED','REJECTED')), recipient_list TEXT, rationale TEXT, revised_expectation TEXT, created_by_person_id TEXT NOT NULL, FOREIGN KEY (case_id) REFERENCES legal_review_cases(case_id));

CREATE TABLE business_calendar_days (calendar_date TEXT NOT NULL, calendar_id TEXT NOT NULL, weekday_name TEXT NOT NULL, is_weekend INTEGER NOT NULL CHECK (is_weekend IN (0,1)), is_federal_holiday INTEGER NOT NULL CHECK (is_federal_holiday IN (0,1)), is_campus_closure INTEGER NOT NULL CHECK (is_campus_closure IN (0,1)), is_business_day INTEGER NOT NULL CHECK (is_business_day IN (0,1)), closure_reason TEXT, PRIMARY KEY (calendar_date, calendar_id));